import React, { useState } from 'react';

const existingRequirements = [
  { id: 'REQ-001', position: 'Assistant Professor', department: 'Computer Science', date: '2025-10-15', status: 'Approved' },
  { id: 'REQ-002', position: 'Lab Technician', department: 'Physics', date: '2025-10-18', status: 'Pending' },
  { id: 'REQ-003', position: 'Admissions Counselor', department: 'Admissions Office', date: '2025-10-20', status: 'Rejected' },
  { id: 'REQ-004', position: 'Junior Librarian', department: 'Library', date: '2025-10-21', status: 'Pending' },
];

const RequirementPage = () => {
  const [formData, setFormData] = useState({ position: '', department: '', positions: 1, justification: '' });

  const getStatusBadgeClass = (status) => {
    switch (status) {
      case 'Approved': return 'bg-green-100 text-green-800';
      case 'Pending': return 'bg-yellow-100 text-yellow-800';
      case 'Rejected': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const handleInputChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = (e) => {
    e.preventDefault();
    alert('Request submitted successfully!');
  };

  const stats = existingRequirements.reduce((acc, req) => {
    acc.total += 1;
    acc[req.status.toLowerCase()] = (acc[req.status.toLowerCase()] || 0) + 1;
    return acc;
  }, { total: 0 });

  return (
    <>
      <header className="bg-card-light dark:bg-card-dark p-4 border-b border-border-light dark:border-border-dark sticky top-0 z-10">
        <h1 className="text-2xl font-semibold text-text-light dark:text-text-dark">Raise Hiring Requirement</h1>
      </header>

      <div className="p-8 grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">

        {/* Form */}
        <div className="lg:col-span-1 bg-card-light dark:bg-card-dark p-6 rounded-lg shadow-md space-y-4">
          <h3 className="text-lg font-semibold text-text-light dark:text-text-dark mb-4">New Position Request</h3>

          {/* Stats inside form card */}
          <div className="flex justify-between mb-4 text-sm text-subtext-light dark:text-subtext-dark">
            <div>Total: {stats.total}</div>
            <div>Approved: {stats.approved || 0}</div>
            <div>Pending: {stats.pending || 0}</div>
            <div>Rejected: {stats.rejected || 0}</div>
          </div>

          <form className="space-y-4" onSubmit={handleSubmit}>
            <div>
              <label htmlFor="position" className="block text-sm font-medium text-subtext-light dark:text-subtext-dark mb-1">Position / Title</label>
              <input
                type="text"
                id="position"
                name="position"
                value={formData.position}
                onChange={handleInputChange}
                className="w-full bg-background-light dark:bg-background-dark border border-border-light dark:border-border-dark rounded-md shadow-sm px-3 py-2"
                placeholder="Assistant Professor"
                required
              />
            </div>

            <div>
              <label htmlFor="department" className="block text-sm font-medium text-subtext-light dark:text-subtext-dark mb-1">Department / Faculty</label>
              <select
                id="department"
                name="department"
                value={formData.department}
                onChange={handleInputChange}
                className="w-full bg-background-light dark:bg-background-dark border border-border-light dark:border-border-dark rounded-md shadow-sm px-3 py-2"
                required
              >
                <option value="">-- Select Department --</option>
                <option>Faculty of Engineering</option>
                <option>Faculty of Arts & Commerce</option>
                <option>Administration</option>
              </select>
            </div>

            <div>
              <label htmlFor="positions" className="block text-sm font-medium text-subtext-light dark:text-subtext-dark mb-1">Number of Positions</label>
              <input
                type="number"
                id="positions"
                name="positions"
                min="1"
                value={formData.positions}
                onChange={handleInputChange}
                className="w-full bg-background-light dark:bg-background-dark border border-border-light dark:border-border-dark rounded-md shadow-sm px-3 py-2"
              />
            </div>

            <div>
              <label htmlFor="justification" className="block text-sm font-medium text-subtext-light dark:text-subtext-dark mb-1">Justification</label>
              <textarea
                id="justification"
                name="justification"
                value={formData.justification}
                onChange={handleInputChange}
                rows={4}
                className="w-full bg-background-light dark:bg-background-dark border border-border-light dark:border-border-dark rounded-md shadow-sm px-3 py-2"
                placeholder="Explain why this position is needed..."
              ></textarea>
            </div>

            <div className="flex gap-2 pt-2">
              <button type="submit" className="flex-1 bg-primary text-white px-4 py-2 rounded-lg font-medium hover:bg-blue-600">Submit</button>
              <button type="reset" className="flex-1 bg-gray-200 text-gray-700 px-4 py-2 rounded-lg hover:bg-gray-300">Reset</button>
            </div>
          </form>
        </div>

        {/* Table */}
        <div className="lg:col-span-2 bg-card-light dark:bg-card-dark p-6 rounded-lg shadow-md">
          <h3 className="text-lg font-semibold text-text-light dark:text-text-dark mb-4">Submitted Requirements</h3>

          {existingRequirements.length === 0 ? (
            <div className="text-center py-10 text-subtext-light dark:text-subtext-dark">No hiring requests yet.</div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm text-left border-collapse">
                <thead className="text-xs text-subtext-light dark:text-subtext-dark uppercase bg-background-light dark:bg-background-dark">
                  <tr>
                    <th className="px-6 py-3">Request ID</th>
                    <th className="px-6 py-3">Position</th>
                    <th className="px-6 py-3">Department</th>
                    <th className="px-6 py-3">Date Submitted</th>
                    <th className="px-6 py-3">Status</th>
                    <th className="px-6 py-3">Action</th>
                  </tr>
                </thead>
                <tbody>
                  {existingRequirements.map((req) => (
                    <tr key={req.id} className="border-b border-border-light dark:border-border-dark hover:bg-gray-50 dark:hover:bg-gray-800/50">
                      <td className="px-6 py-4 font-medium">{req.id}</td>
                      <td className="px-6 py-4">{req.position}</td>
                      <td className="px-6 py-4">{req.department}</td>
                      <td className="px-6 py-4">{req.date}</td>
                      <td className="px-6 py-4">
                        <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusBadgeClass(req.status)}`}>
                          {req.status}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <button className="text-blue-600 hover:underline text-sm">View</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </>
  );
};

export default RequirementPage;
